function findOrder(numCourses, prerequisites) {
  const next = Array.from({ length: numCourses }, () => []);
  const indegree = new Array(numCourses).fill(0);
  for (const [course, pre] of prerequisites) {
    next[pre].push(course);
    indegree[course]++;
  }
  const order = [];
  for (let c = 0; c < numCourses; c++) {
    if (indegree[c] === 0) order.push(c);   // ready now
  }
  for (let head = 0; head < order.length; head++) {   // the order list is the queue
    for (const d of next[order[head]]) {
      indegree[d]--;
      if (indegree[d] === 0) order.push(d); // all of d's prerequisites are placed
    }
  }
  return order.length === numCourses ? order : [];    // a short list means a cycle
}

int[] findOrder(int numCourses, int[][] prerequisites) {
    List<List<Integer>> next = new ArrayList<>();
    for (int i = 0; i < numCourses; i++) next.add(new ArrayList<>());
    int[] indegree = new int[numCourses];
    for (int[] p : prerequisites) {
        next.get(p[1]).add(p[0]);
        indegree[p[0]]++;
    }
    int[] order = new int[numCourses];
    int size = 0;
    for (int c = 0; c < numCourses; c++) {
        if (indegree[c] == 0) order[size++] = c;        // ready now
    }
    for (int head = 0; head < size; head++) {           // the order array is the queue
        for (int d : next.get(order[head])) {
            if (--indegree[d] == 0) order[size++] = d;  // all of d's prerequisites are placed
        }
    }
    return size == numCourses ? order : new int[0];     // a short list means a cycle
}

