function findOrder(numCourses, prerequisites) {
  const next = Array.from({ length: numCourses }, () => []);
  for (const [course, pre] of prerequisites) next[pre].push(course);
  const state = new Array(numCourses).fill(0);   // 0 = new, 1 = on the current path, 2 = done
  const finished = [];                           // each course lands after all it unlocks
  const visit = (c) => {
    if (state[c] === 1) return false;            // back onto the current path: a cycle
    if (state[c] === 2) return true;             // already placed
    state[c] = 1;
    for (const d of next[c]) {
      if (!visit(d)) return false;
    }
    state[c] = 2;
    finished.push(c);                            // everything c unlocks is already placed
    return true;
  };
  for (let c = 0; c < numCourses; c++) {
    if (!visit(c)) return [];
  }
  return finished.reverse();                     // last to finish = first to take
}

def find_order(num_courses, prerequisites):
    nxt = [[] for _ in range(num_courses)]
    for course, pre in prerequisites:
        nxt[pre].append(course)
    state = [0] * num_courses             # 0 = new, 1 = on the current path, 2 = done
    finished = []                         # each course lands after all it unlocks

    def visit(c):
        if state[c] == 1:
            return False                  # back onto the current path: a cycle
        if state[c] == 2:
            return True                   # already placed
        state[c] = 1
        if not all(visit(d) for d in nxt[c]):
            return False
        state[c] = 2
        finished.append(c)                # everything c unlocks is already placed
        return True

    if not all(visit(c) for c in range(num_courses)):
        return []
    return finished[::-1]                 # last to finish = first to take

int[] findOrder(int numCourses, int[][] prerequisites) {
    List<List<Integer>> next = new ArrayList<>();
    for (int i = 0; i < numCourses; i++) next.add(new ArrayList<>());
    for (int[] p : prerequisites) next.get(p[1]).add(p[0]);
    int[] state = new int[numCourses];                  // 0 = new, 1 = on the current path, 2 = done
    List<Integer> finished = new ArrayList<>();         // each course lands after all it unlocks
    for (int c = 0; c < numCourses; c++) {
        if (!visit(next, state, finished, c)) return new int[0];
    }
    int[] order = new int[numCourses];
    for (int i = 0; i < numCourses; i++) order[i] = finished.get(numCourses - 1 - i);   // reversed
    return order;
}

boolean visit(List<List<Integer>> next, int[] state, List<Integer> finished, int c) {
    if (state[c] == 1) return false;                    // back onto the current path: a cycle
    if (state[c] == 2) return true;                     // already placed
    state[c] = 1;
    for (int d : next.get(c)) {
        if (!visit(next, state, finished, d)) return false;
    }
    state[c] = 2;
    finished.add(c);                                    // everything c unlocks is already placed
    return true;
}

bool visit(vector<vector<int>>& next, vector<int>& state, vector<int>& finished, int c) {
    if (state[c] == 1) return false;                    // back onto the current path: a cycle
    if (state[c] == 2) return true;                     // already placed
    state[c] = 1;
    for (int d : next[c]) {
        if (!visit(next, state, finished, d)) return false;
    }
    state[c] = 2;
    finished.push_back(c);                              // everything c unlocks is already placed
    return true;
}

vector<int> findOrder(int numCourses, vector<vector<int>>& prerequisites) {
    vector<vector<int>> next(numCourses);
    for (auto& p : prerequisites) next[p[1]].push_back(p[0]);
    vector<int> state(numCourses, 0);                   // 0 = new, 1 = on the current path, 2 = done
    vector<int> finished;                               // each course lands after all it unlocks
    for (int c = 0; c < numCourses; c++) {
        if (!visit(next, state, finished, c)) return {};
    }
    reverse(finished.begin(), finished.end());          // last to finish = first to take
    return finished;
}
